(1037139, 124587, 22384, '<td valign="top">Witty, witty, witty. Great image, too, by the way.</td>', 'Witty, witty, witty. Great image, too, by the way.', '2004-11-29 23:43:30.000000', NULL, 1),
(1037144, 124332, 22384, '<td valign="top">Funny idea. The shot is lacking something. Maybe the can looks too clean and dry and the bear a little out of focus. Creative concept.</td>', 'Funny idea. The shot is lacking something. Maybe the can looks too clean and dry and the bear a little out of focus. Creative concept.', '2004-11-29 23:44:58.000000', NULL, 1),
(1037145, 124305, 25468, '<td valign="top">Dude, seriously, this is awesome in too many aspects to list here. Me and the wife are rollin''</td>', 'Dude, seriously, this is awesome in too many aspects to list here. Me and the wife are rollin''', '2004-11-29 23:45:01.000000', NULL, 1),
(1037148, 124706, 25468, '<td valign="top">If it weren''t for the humorous sign I wouldn''t like this.</td>', 'If it weren''t for the humorous sign I wouldn''t like this.', '2004-11-29 23:46:02.000000', NULL, 1),
(1037149, 124331, 22384, '<td valign="top">I love this shot. The posture and positioning of the man and the creature do make it look like they are in deep conversation. Great range of values. The subject''s white hair acts as an excellent contrast to the darkness of the creature. That white hair, for some reason, makes the shot transcend for me.</td>', 'I love this shot. The posture and positioning of the man and the creature do make it look like they are in deep conversation. Great range of values. The subject''s white hair acts as an excellent contrast to the darkness of the creature. That white hair, for some reason, makes the shot transcend for me.', '2004-11-29 23:47:02.000000', NULL, 1),
(1037153, 124445, 22384, '<td valign="top">Okay, more toilet humor. I just sorta feel sorry for the guy. The positioning and facial expression make this a little too real to be funny. I feel a bit like I am violating the subject''s personal pain.</td>', 'Okay, more toilet humor. I just sorta feel sorry for the guy. The positioning and facial expression make this a little too real to be funny. I feel a bit like I am violating the subject''s personal pain.', '2004-11-29 23:49:11.000000', NULL, 1),
