(1047314, 124650, 23362, '<td valign="top">Photographically handled rather well but the "cat scan" as subjectmatter for humor has become rather trite.</td>', 'Photographically handled rather well but the "cat scan" as subjectmatter for humor has become rather trite.', '2004-12-05 17:12:41.000000', NULL, 1),
(1047317, 124508, 23362, '<td valign="top">Cute shot...but the only thing I can think of that would make this funny along with the idea of punch line would be to see a bird standing behind them.</td>', 'Cute shot...but the only thing I can think of that would make this funny along with the idea of punch line would be to see a bird standing behind them.', '2004-12-05 17:14:52.000000', NULL, 1),
(1047320, 124146, 23362, '<td valign="top">That''s some "exposure." 10 stars to the original artist...7 stars to the photog that found and recorded this funny image</td>', 'That''s some "exposure." 10 stars to the original artist...7 stars to the photog that found and recorded this funny image', '2004-12-05 17:19:04.000000', NULL, 1),
(1047325, 124323, 23362, '<td valign="top">Which came first? The toilet or the sign?  I think for my own handling of a picture like this (as a setup) would have been to have the sign on a pole with the pole stuck into the bowl...or at least have the toilet lid up...</td>', 'Which came first? The toilet or the sign?  I think for my own handling of a picture like this (as a setup) would have been to have the sign on a pole with the pole stuck into the bowl...or at least have the toilet lid up...', '2004-12-05 17:26:16.000000', NULL, 1),
(1047326, 124575, 23362, '<td valign="top">Ha! I like this one...I always like signs that state the obvious. :-)<br/>Good eye!</td>', 'Ha! I like this one...I always like signs that state the obvious. :-)Good eye!', '2004-12-05 17:28:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1047329, 124536, 30093, '<td valign="top">Brilliant pose!</td>', 'Brilliant pose!', '2004-12-05 17:31:15.000000', NULL, 1),
(1047331, 124567, 23362, '<td valign="top">Fantastic birding photo...just wish there had been just a little more depth of field...darn! Still a fine effort! Good caption too... Perhaps cranking up the contrast a little might give the incoming bird a little more sharpness, shape and form...I think it would be worth a try. If you do...please let me know your results and if you think it helped...okay?</td>', 'Fantastic birding photo...just wish there had been just a little more depth of field...darn! Still a fine effort! Good caption too... Perhaps cranking up the contrast a little might give the incoming bird a little more sharpness, shape and form...I think it would be worth a try. If you do...please let me know your results and if you think it helped...okay?', '2004-12-05 17:33:59.000000', NULL, 1),
(1047332, 124156, 2158, '<td valign="top">Nice picture, but in my opinion, without the title it doesn''t fit the challenge.</td>', 'Nice picture, but in my opinion, without the title it doesn''t fit the challenge.', '2004-12-05 17:34:23.000000', NULL, 1),
(1047350, 124695, 23362, '<td valign="top">This must relate to some polker advice...but I don''t remember the saying or logic so I can not relate...sorry.  However, I do like the nature of the  lighting and the center of interest not being centered. I''m wondering if there was a reason the photographer chose a "black" rather than "red" card? I''m pretty sure to those that get this message it would be funny...so I give it an 8.</td>', 'This must relate to some polker advice...but I don''t remember the saying or logic so I can not relate...sorry.  However, I do like the nature of the  lighting and the center of interest not being centered. I''m wondering if there was a reason the photographer chose a "black" rather than "red" card? I''m pretty sure to those that get this message it would be funny...so I give it an 8.', '2004-12-05 17:49:24.000000', NULL, 1),
(1047357, 124024, 27605, '<td valign="top">What a doll.  I do like the "floating hands" effect, very effective especially holding the lipstick.</td>', 'What a doll.  I do like the "floating hands" effect, very effective especially holding the lipstick.', '2004-12-05 17:52:20.000000', NULL, 1),
(1047362, 124475, 27605, '<td valign="top">Scored highly by me on the "funny" factor.  Technical critique a bit harsher... needs sharper focus on the poor victim''s ears, for example.  Great creativity however!</td>', 'Scored highly by me on the "funny" factor.  Technical critique a bit harsher... needs sharper focus on the poor victim''s ears, for example.  Great creativity however!', '2004-12-05 17:54:29.000000', NULL, 1),
(1047368, 124695, 27605, '<td valign="top">Like the thought!  I think the photo could be improved with a closer  shot, maybe a slightly larger hole with the Ace flat in the bottom.  Creative!</td>', 'Like the thought!  I think the photo could be improved with a closer  shot, maybe a slightly larger hole with the Ace flat in the bottom.  Creative!', '2004-12-05 17:55:58.000000', NULL, 1),
(1047369, 124122, 23362, '<td valign="top">Wow! What a great idea for a photo and it''s funny too! Way To Go!  Adding this pic as one of my favorites!</td>', 'Wow! What a great idea for a photo and it''s funny too! Way To Go!  Adding this pic as one of my favorites!', '2004-12-05 17:56:15.000000', NULL, 1),
(1047371, 124453, 23362, '<td valign="top">Ha! Somebody thinks you''re pretty special!</td>', 'Ha! Somebody thinks you''re pretty special!', '2004-12-05 17:58:05.000000', NULL, 1),
(1047372, 124677, 27605, '<td valign="top">I would swear that goat is reading!  Funny shot.</td>', 'I would swear that goat is reading!  Funny shot.', '2004-12-05 17:58:09.000000', NULL, 1),
(1047374, 124156, 27605, '<td valign="top">I really like the photo, but I think it struggles to make it in the "HUMOR" challenge, even considering the title.  Scored 6 by me...</td>', 'I really like the photo, but I think it struggles to make it in the "HUMOR" challenge, even considering the title.  Scored 6 by me...', '2004-12-05 17:59:20.000000', NULL, 1),
(1047376, 124031, 27605, '<td valign="top">Larger photo would have improved this one!  Background not busy per se, but a distraction to me nonetheless.</td>', 'Larger photo would have improved this one!  Background not busy per se, but a distraction to me nonetheless.', '2004-12-05 18:01:06.000000', NULL, 1),
(1047380, 123887, 23362, '<td valign="top">"Coprophobia" isn''t in my Merriam Webster..so I''ll need a little help with this one. Technically speaking looks, to me,  on my monitor the image need a little white balancing. And, I''m pretty sure if I knew what fear coprophobia is I''d find this funny. I like the design and placement of the person and objects.</td>', '"Coprophobia" isn''t in my Merriam Webster..so I''ll need a little help with this one. Technically speaking looks, to me,  on my monitor the image need a little white balancing. And, I''m pretty sure if I knew what fear coprophobia is I''d find this funny. I like the design and placement of the person and objects.', '2004-12-05 18:04:24.000000', NULL, 1),
(1047388, 124475, 23362, '<td valign="top">I have "issues." Photos such as this I find depressing...but I know they should be funny...so forgive me for not laughing. Excellent marks for a photograph well done! Nice, nice...nice!  The simplicity makes this a big winner in my book!</td>', 'I have "issues." Photos such as this I find depressing...but I know they should be funny...so forgive me for not laughing. Excellent marks for a photograph well done! Nice, nice...nice!  The simplicity makes this a big winner in my book!', '2004-12-05 18:08:51.000000', NULL, 1),
(1047391, 124331, 23362, '<td valign="top">Fine image! I like everything about it...everything!</td>', 'Fine image! I like everything about it...everything!', '2004-12-05 18:12:22.000000', NULL, 1),
(1047395, 123834, 23362, '<td valign="top">Nice use of color with black and white!</td>', 'Nice use of color with black and white!', '2004-12-05 18:15:29.000000', NULL, 1),
(1047407, 124587, 23362, '<td valign="top">Excellent use of light, shape and form...but I don''t get the angel part. Is this a measuring device on a scale? Is angel used as a term for the insturment resting on his head? Is Angel the name of a company making doctor''s scales?  Or am I misunderstanding what''s going on here? Perhaps it''s a spelling error? Maybe you were saying "Touched By An Angle?"  That I would find funny!   I''ll say 7 just for the strength of the lighting. But, that''s only because a 6.5 is not an option...LOL</td>', 'Excellent use of light, shape and form...but I don''t get the angel part. Is this a measuring device on a scale? Is angel used as a term for the insturment resting on his head? Is Angel the name of a company making doctor''s scales?  Or am I misunderstanding what''s going on here? Perhaps it''s a spelling error? Maybe you were saying "Touched By An Angle?"  That I would find funny!   I''ll say 7 just for the strength of the lighting. But, that''s only because a 6.5 is not an option...LOL', '2004-12-05 18:23:58.000000', NULL, 1),
(1047413, 123306, 2158, '<td valign="top">Interesting idea, but it looks like you have increased the saturation too much here, creating some really strange colours on what presumably was meant to be a white background.</td>', 'Interesting idea, but it looks like you have increased the saturation too much here, creating some really strange colours on what presumably was meant to be a white background.', '2004-12-05 18:26:58.000000', NULL, 1),
(1047415, 124492, 23362, '<td valign="top">(?) Did you make this craft for this picture? If so I''d give you a 7. Did you use a craft made by someone else to illustrate your "humor" picture? If so I''d give you a 5. So therefore...I give you a 6.</td>', '(?) Did you make this craft for this picture? If so I''d give you a 7. Did you use a craft made by someone else to illustrate your "humor" picture? If so I''d give you a 5. So therefore...I give you a 6.', '2004-12-05 18:28:57.000000', NULL, 1),
(1047418, 124199, 23362, '<td valign="top">Ha! The only one left "stand up" sober! It''s got to be used as a birthday card cover shot...for sure!</td>', 'Ha! The only one left "stand up" sober! It''s got to be used as a birthday card cover shot...for sure!', '2004-12-05 18:31:15.000000', NULL, 1),
(1047420, 123931, 23362, '<td valign="top">Makes me dizzy...LOL  I like the combination of colors...Kinda comical to me...good going!</td>', 'Makes me dizzy...LOL  I like the combination of colors...Kinda comical to me...good going!', '2004-12-05 18:33:57.000000', NULL, 1),
(1047421, 124258, 23362, '<td valign="top">Ha!</td>', 'Ha!', '2004-12-05 18:35:24.000000', NULL, 1),
(1047425, 123630, 23362, '<td valign="top">Ha! I gotta have the streak free kind for my hard to clean areas!</td>', 'Ha! I gotta have the streak free kind for my hard to clean areas!', '2004-12-05 18:39:19.000000', NULL, 1),
(1047427, 123516, 23362, '<td valign="top">Good! You show-offs in the warm southland! And I''m freezing my showballs off here in Northern Utah!  I''d like to see one add-on to this pic and that would be an attractive model with sunglasses and wearing something ever so skimpy to really drive the point home!  LOL</td>', 'Good! You show-offs in the warm southland! And I''m freezing my showballs off here in Northern Utah!  I''d like to see one add-on to this pic and that would be an attractive model with sunglasses and wearing something ever so skimpy to really drive the point home!  LOL', '2004-12-05 18:43:10.000000', NULL, 1),
(1047431, 124327, 23362, '<td valign="top">The belensing of an innocent camera!  Don''t do it until FOX news crews depart...okay? You know how politically incorrect this all is?  :::grinning:::<br/>Could we compromise? Perhaps you''d accept a 6 plus a 4?  LOL<br/>(By The Way...is that a Christian owned camera or one that goes "CRICK??)</td>', 'The belensing of an innocent camera!  Don''t do it until FOX news crews depart...okay? You know how politically incorrect this all is?  :::grinning:::Could we compromise? Perhaps you''d accept a 6 plus a 4?  LOL(By The Way...is that a Christian owned camera or one that goes "CRICK??)', '2004-12-05 18:51:52.000000', NULL, 1),
(1047435, 124156, 23362, '<td valign="top">Ha!  Good one!  And, a great animal portrait too!  Way to go!!</td>', 'Ha!  Good one!  And, a great animal portrait too!  Way to go!!', '2004-12-05 18:53:58.000000', NULL, 1),
(1047438, 123385, 23362, '<td valign="top">Nice image...just wish I knew if you make the idea up as a craft? I think most of the points should go to the creator of the original idea rather than the finder with a camera. If you made these chimes I''d give you a 10. If you documented these chimes, thought up by someone else, I''d give you a 6...therefore a 8 :-)</td>', 'Nice image...just wish I knew if you make the idea up as a craft? I think most of the points should go to the creator of the original idea rather than the finder with a camera. If you made these chimes I''d give you a 10. If you documented these chimes, thought up by someone else, I''d give you a 6...therefore a 8 :-)', '2004-12-05 19:01:07.000000', NULL, 1),
(1047448, 124700, 23362, '<td valign="top">Ha!  Well done!  Nice positioning of the hands and they look clean and well manicured too.  Excellent lighting with a good "play down" to the props in the background. Here all this time I thought their serving cat meat was just an urban legend!  LOL  :-D</td>', 'Ha!  Well done!  Nice positioning of the hands and they look clean and well manicured too.  Excellent lighting with a good "play down" to the props in the background. Here all this time I thought their serving cat meat was just an urban legend!  LOL  :-D', '2004-12-05 19:08:42.000000', NULL, 1),
(1047455, 124541, 23362, '<td valign="top">Tuff Guy...Huh?  Bet they never thought to use this technique at A''bu''grabe prison (or however, the hell,  it''s spelled)  LOL</td>', 'Tuff Guy...Huh?  Bet they never thought to use this technique at A''bu''grabe prison (or however, the hell,  it''s spelled)  LOL', '2004-12-05 19:13:31.000000', NULL, 1),
(1047460, 124523, 23362, '<td valign="top">WOW!  Great image!  I''d think this one deserves an eleven...but only in some other category than humor. The technique and colors are dynamite! Just the images in the drops are too small to carry the humor to me...at least on my monitor. I think there may be little bunny or bee faces or whatever there...but I can''t make them out for sure. So with that in mind...an 8.</td>', 'WOW!  Great image!  I''d think this one deserves an eleven...but only in some other category than humor. The technique and colors are dynamite! Just the images in the drops are too small to carry the humor to me...at least on my monitor. I think there may be little bunny or bee faces or whatever there...but I can''t make them out for sure. So with that in mind...an 8.', '2004-12-05 19:19:23.000000', NULL, 1),
(1047471, 124662, 23362, '<td valign="top">I think...Super well done as a gallery image...but a bit off the graze for a humor pic (even with the caption) .</td>', 'I think...Super well done as a gallery image...but a bit off the graze for a humor pic (even with the caption) .', '2004-12-05 19:25:46.000000', NULL, 1),
(1047479, 124454, 23362, '<td valign="top">I hope Santa didn''t take this reversing of roles too far and wet himself!  LOL</td>', 'I hope Santa didn''t take this reversing of roles too far and wet himself!  LOL', '2004-12-05 19:31:13.000000', NULL, 1),
(1047488, 124634, 23362, '<td valign="top">A wonderful portrait...really a fetching photograph... but,  the humor part falls short  for me..  However, it''s a successful picture in it''s own rights, I''d say it''s a "bell ringer."    One other thing, and it may be my monitor, I''d like to see the contrast taken up just a tiny amount. I don''t think it will kill off the wonderful shadow detail but rather give the image a little more "snap."</td>', 'A wonderful portrait...really a fetching photograph... but,  the humor part falls short  for me..  However, it''s a successful picture in it''s own rights, I''d say it''s a "bell ringer."    One other thing, and it may be my monitor, I''d like to see the contrast taken up just a tiny amount. I don''t think it will kill off the wonderful shadow detail but rather give the image a little more "snap."', '2004-12-05 19:38:08.000000', NULL, 1),
(1047491, 124664, 23362, '<td valign="top">Nine!</td>', 'Nine!', '2004-12-05 19:39:27.000000', NULL, 1),
(1047498, 124045, 23362, '<td valign="top">For me not enough organization to the image. I really don''t see the flower and the lighting on the ice is rather ho-hum. Perhaps back lighting may have done something more magical?</td>', 'For me not enough organization to the image. I really don''t see the flower and the lighting on the ice is rather ho-hum. Perhaps back lighting may have done something more magical?', '2004-12-05 19:42:35.000000', NULL, 1),
(1047516, 124316, 23362, '<td valign="top">LOL... I used to be an educator of photography at a University, here in the U.S.  and would only flip dimes... as a half dollar was usually too precious to put at risk of going down a heat vent!   :::grin:::  Okay,  Truth be told...<br/>I never did resort to the filp of a coin to "confirm" a grade.  <br/>Your picture is clever, creative and smacks at the truth...or at least the truth as to how some students think their grades are being determined.</td>', 'LOL... I used to be an educator of photography at a University, here in the U.S.  and would only flip dimes... as a half dollar was usually too precious to put at risk of going down a heat vent!   :::grin:::  Okay,  Truth be told...I never did resort to the filp of a coin to "confirm" a grade.  Your picture is clever, creative and smacks at the truth...or at least the truth as to how some students think their grades are being determined.', '2004-12-05 19:58:28.000000', NULL, 1),
(1047519, 123385, 10080, '<td valign="top">Hehehe...I have a redneck doorbell that I was gonna use for the challenge. I do like your color composition and dof on the shot, and it is one of the funnier shots in the challenge.8</td>', 'Hehehe...I have a redneck doorbell that I was gonna use for the challenge. I do like your color composition and dof on the shot, and it is one of the funnier shots in the challenge.8', '2004-12-05 20:04:27.000000', NULL, 1),
(1047520, 123902, 23362, '<td valign="top">Oh, but I want a whole greenhouse filled with them!  Excellent concept for the humor category.  :::counting how many leaves this plant really has 1,2,3,4,5... Hmmm...  Far Out...Man!!:::  ...just kidding...      :-)</td>', 'Oh, but I want a whole greenhouse filled with them!  Excellent concept for the humor category.  :::counting how many leaves this plant really has 1,2,3,4,5... Hmmm...  Far Out...Man!!:::  ...just kidding...      :-)', '2004-12-05 20:04:28.000000', NULL, 1),
(1047522, 124550, 23362, '<td valign="top">Ha!  Funny-Funny! <br/>Just wished the little human had a little more expression.</td>', 'Ha!  Funny-Funny! Just wished the little human had a little more expression.', '2004-12-05 20:07:14.000000', NULL, 1),
(1047524, 124130, 23362, '<td valign="top">Nature is indifferent...it is I who is confused!  What am I missing here that is funny?</td>', 'Nature is indifferent...it is I who is confused!  What am I missing here that is funny?', '2004-12-05 20:10:58.000000', NULL, 1),
(1047526, 124638, 23362, '<td valign="top">Do cats get blood-shot eyes from lack of sleep?  I think we may have some proof here...that they do. :-)  LOL</td>', 'Do cats get blood-shot eyes from lack of sleep?  I think we may have some proof here...that they do. :-)  LOL', '2004-12-05 20:13:21.000000', NULL, 1),
(1047531, 124315, 23362, '<td valign="top">I''m sorry, I don''t pick up on the humor here. Perhaps the submission is from a different culture than mine...which could explain the difference in humor? Anyway, I''m an inlander and have no idea what''s funny to clammers.  :-)  So, for my lack of understanding... I''ll give this a 7 rather than a lower score.  And, it''s kind of a cool picture to look at, nevertheless.</td>', 'I''m sorry, I don''t pick up on the humor here. Perhaps the submission is from a different culture than mine...which could explain the difference in humor? Anyway, I''m an inlander and have no idea what''s funny to clammers.  :-)  So, for my lack of understanding... I''ll give this a 7 rather than a lower score.  And, it''s kind of a cool picture to look at, nevertheless.', '2004-12-05 20:19:22.000000', NULL, 1),
(1047532, 124205, 1031, '<td valign="top">Looks healthier than the average barroom concoction.</td>', 'Looks healthier than the average barroom concoction.', '2004-12-05 20:19:37.000000', NULL, 1),
(1047541, 124490, 23362, '<td valign="top">Ha!  Tell me this photo wasn''t made at a Fire Station!  But, I''d wear them...I''m retired. What do I care what those rock throwing peasants think?  The laughs one would get wearing those in the super market!  Well, maybe not in NYC...but elswhere in the world.  Co-ol Shot! Thanks for sharing...and good title too.</td>', 'Ha!  Tell me this photo wasn''t made at a Fire Station!  But, I''d wear them...I''m retired. What do I care what those rock throwing peasants think?  The laughs one would get wearing those in the super market!  Well, maybe not in NYC...but elswhere in the world.  Co-ol Shot! Thanks for sharing...and good title too.', '2004-12-05 20:26:34.000000', NULL, 1),
(1047550, 123834, 1031, '<td valign="top">Maybe it doesn''t apply to the highway department.</td>', 'Maybe it doesn''t apply to the highway department.', '2004-12-05 20:28:50.000000', NULL, 1),
(1047555, 124491, 23362, '<td valign="top">So this is what pets do when you''re not at home?  Hmmm...Now I have to get a porn filter for my two dogs?  Excellent idea...and funny! You get a high score from me!</td>', 'So this is what pets do when you''re not at home?  Hmmm...Now I have to get a porn filter for my two dogs?  Excellent idea...and funny! You get a high score from me!', '2004-12-05 20:30:48.000000', NULL, 1),
(1047558, 123385, 1031, '<td valign="top">Hmmm .. there are many possible variations of this too -- very inspiring : )</td>', 'Hmmm .. there are many possible variations of this too -- very inspiring : )', '2004-12-05 20:31:50.000000', NULL, 1),
(1047562, 124571, 23362, '<td valign="top">Somehow I was expecting to see a FROST HEAVE sign!  LOL...maybe we only have frost heave signs in my neck of the woods? Anyway, you have an interesting and colorful photo and I see it''s been validated...so Way To Go!</td>', 'Somehow I was expecting to see a FROST HEAVE sign!  LOL...maybe we only have frost heave signs in my neck of the woods? Anyway, you have an interesting and colorful photo and I see it''s been validated...so Way To Go!', '2004-12-05 20:35:50.000000', NULL, 1),
